/* math_ops.h */
#ifndef CODESAATHI_MATH_OPS_H
#define CODESAATHI_MATH_OPS_H
int add_values(int left, int right);
#endif

/* math_ops.c */
#include "math_ops.h"
int add_values(int left, int right)
{
    return left + right;
}

/* main.c */
#include <stdio.h>
#include "math_ops.h"
int main(void)
{
    printf("sum=%d\n", add_values(2, 3));
    return 0;
}

/* Build: cc -std=c17 -Wall -Wextra -Wpedantic main.c math_ops.c -o app */

/* From a directory containing main.c and math_ops.c: */
/* cc -std=c17 -Wall -Wextra -Wpedantic -c main.c -o main.o */
/* cc -std=c17 -Wall -Wextra -Wpedantic -c math_ops.c -o math_ops.o */
/* cc main.o math_ops.o -o app */

#include <stdio.h>
int main(void)
{
    puts("The linker combines object files into a program.");
    return 0;
}
